"""Core MLIR IR data structures.

This module is the foundation of the whole stack: the CIRCT hardware dialects in
:mod:`src.circt` and the K-inspired semantic layer in :mod:`src.k_circt` are both
built on the operations / blocks / regions / modules defined here.

The design mirrors upstream MLIR closely enough that the concepts transfer:

* :class:`MLIRContext` owns dialect registration and uniqued types.
* :class:`Type` and :class:`Attribute` are immutable, hashable value objects.
* :class:`Value` is either an :class:`OpResult` or a :class:`BlockArgument`, and
  tracks its uses so that ``replace_all_uses_with`` and DCE are cheap.
* :class:`Operation` holds operands, results, attributes, successors and nested
  :class:`Region` objects; regions hold :class:`Block` objects; blocks hold
  operations.  That is the classic MLIR three-level nesting.
"""
from __future__ import annotations

import itertools
from abc import ABC, abstractmethod
from enum import Enum, auto
from typing import (
    Any,
    Callable,
    Dict,
    Iterable,
    Iterator,
    List,
    Optional,
    Sequence,
    Tuple,
)

__all__ = [
    "MLIRContext",
    "Dialect",
    "Location",
    "Trait",
    "Type",
    "IntegerType",
    "FloatType",
    "IndexType",
    "NoneType_",
    "FunctionType",
    "TupleType",
    "OpaqueType",
    "Attribute",
    "UnitAttr",
    "BoolAttr",
    "IntegerAttr",
    "FloatAttr",
    "StringAttr",
    "TypeAttr",
    "ArrayAttr",
    "DictAttr",
    "FlatSymbolRefAttr",
    "Value",
    "OpResult",
    "BlockArgument",
    "OpOperand",
    "Operation",
    "Block",
    "Region",
    "ModuleOp",
    "OpBuilder",
    "InsertionPoint",
    "Verifier",
    "VerificationError",
    "ParseError",
    "WalkOrder",
    "SymbolTable",
    "get_default_context",
    "reset_default_context",
]


class ParseError(Exception):
    """Raised when the textual IR cannot be parsed."""

    def __init__(self, message: str, line: int = 0, column: int = 0) -> None:
        self.message = message
        self.line = line
        self.column = column
        if line:
            super().__init__(f"{line}:{column}: {message}")
        else:
            super().__init__(message)


class VerificationError(Exception):
    """Raised when the IR fails verification."""


# ---------------------------------------------------------------------------
# Context / dialects
# ---------------------------------------------------------------------------


class MLIRContext:
    """Owns dialect registration and the uniqued type/attribute caches."""

    def __init__(self, allow_unregistered_dialects: bool = True) -> None:
        self._dialects: Dict[str, "Dialect"] = {}
        self._type_cache: Dict[str, "Type"] = {}
        self._attr_cache: Dict[str, "Attribute"] = {}
        self.allow_unregistered_dialects = allow_unregistered_dialects

    # -- dialects ---------------------------------------------------------
    def register_dialect(self, dialect: "Dialect") -> "Dialect":
        self._dialects[dialect.name] = dialect
        return dialect

    def get_dialect(self, name: str) -> Optional["Dialect"]:
        return self._dialects.get(name)

    def get_or_load_dialect(self, name: str) -> Optional["Dialect"]:
        return self._dialects.get(name)

    @property
    def dialects(self) -> Dict[str, "Dialect"]:
        return dict(self._dialects)

    def is_registered_operation(self, name: str) -> bool:
        dialect_name = name.split(".")[0]
        dialect = self._dialects.get(dialect_name)
        if dialect is None:
            return False
        return dialect.get_operation(name) is not None

    def lookup_operation(self, name: str) -> Optional[type]:
        dialect_name = name.split(".")[0]
        dialect = self._dialects.get(dialect_name)
        if dialect is None:
            return None
        return dialect.get_operation(name)

    # -- uniquing ---------------------------------------------------------
    def get_or_create_type(self, key: str, factory: Callable[[], "Type"]) -> "Type":
        cached = self._type_cache.get(key)
        if cached is None:
            cached = factory()
            self._type_cache[key] = cached
        return cached

    def get_or_create_attribute(
        self, key: str, factory: Callable[[], "Attribute"]
    ) -> "Attribute":
        cached = self._attr_cache.get(key)
        if cached is None:
            cached = factory()
            self._attr_cache[key] = cached
        return cached

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"MLIRContext(dialects={sorted(self._dialects)})"


_DEFAULT_CONTEXT: Optional[MLIRContext] = None


def get_default_context() -> MLIRContext:
    """Return the process-wide default context, creating it on first use.

    Dialect modules register themselves against this context at import time so
    that ``parse(...)`` works without any explicit setup.
    """
    global _DEFAULT_CONTEXT
    if _DEFAULT_CONTEXT is None:
        _DEFAULT_CONTEXT = MLIRContext()
    return _DEFAULT_CONTEXT


def reset_default_context() -> MLIRContext:
    global _DEFAULT_CONTEXT
    _DEFAULT_CONTEXT = MLIRContext()
    return _DEFAULT_CONTEXT


class Dialect:
    """A namespace of operations, types and attributes."""

    def __init__(self, name: str, context: Optional[MLIRContext] = None) -> None:
        self.name = name
        self.context = context if context is not None else get_default_context()
        self._operations: Dict[str, type] = {}
        self._type_parsers: Dict[str, Callable[[str], "Type"]] = {}
        self.context.register_dialect(self)

    # -- operations -------------------------------------------------------
    def register_operation(self, op_class: type) -> type:
        self._operations[op_class.operation_name()] = op_class
        return op_class

    def get_operation(self, name: str) -> Optional[type]:
        return self._operations.get(name)

    @property
    def operations(self) -> Dict[str, type]:
        return dict(self._operations)

    # -- types ------------------------------------------------------------
    def register_type_parser(self, mnemonic: str, parser: Callable[[str], "Type"]) -> None:
        self._type_parsers[mnemonic] = parser

    def parse_type(self, mnemonic: str, body: str) -> Optional["Type"]:
        parser = self._type_parsers.get(mnemonic)
        if parser is None:
            return None
        return parser(body)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"Dialect({self.name!r}, ops={len(self._operations)})"


# ---------------------------------------------------------------------------
# Locations
# ---------------------------------------------------------------------------


class Location:
    """Source location attached to an operation."""

    __slots__ = ("filename", "line", "column", "name")

    def __init__(
        self,
        filename: Optional[str] = None,
        line: int = 0,
        column: int = 0,
        name: Optional[str] = None,
    ) -> None:
        self.filename = filename
        self.line = line
        self.column = column
        self.name = name

    @staticmethod
    def unknown() -> "Location":
        return Location()

    @staticmethod
    def file_line_col(filename: str, line: int, column: int = 0) -> "Location":
        return Location(filename=filename, line=line, column=column)

    @property
    def is_unknown(self) -> bool:
        return self.filename is None and self.name is None

    def __str__(self) -> str:
        if self.name is not None:
            return f'loc("{self.name}")'
        if self.filename is None:
            return "loc(unknown)"
        return f'loc("{self.filename}":{self.line}:{self.column})'

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"Location({self})"


# ---------------------------------------------------------------------------
# Traits
# ---------------------------------------------------------------------------


class Trait(Enum):
    """Operation traits that passes and the verifier query."""

    TERMINATOR = auto()
    PURE = auto()
    CONSTANT_LIKE = auto()
    COMMUTATIVE = auto()
    IDEMPOTENT = auto()
    INVOLUTION = auto()
    SAME_OPERANDS_AND_RESULT_TYPE = auto()
    ISOLATED_FROM_ABOVE = auto()
    SYMBOL = auto()
    SYMBOL_TABLE = auto()
    SINGLE_BLOCK = auto()
    NO_TERMINATOR = auto()
    RETURN_LIKE = auto()
    HAS_CLOCK = auto()


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


class Type(ABC):
    """Base class for all MLIR types.  Types are immutable value objects."""

    @abstractmethod
    def __str__(self) -> str:
        ...

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Type):
            return NotImplemented
        return type(self) is type(other) and str(self) == str(other)

    def __ne__(self, other: object) -> bool:
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self) -> int:
        return hash((type(self).__name__, str(self)))

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"{type(self).__name__}({str(self)!r})"

    # -- convenience predicates ------------------------------------------
    @property
    def is_integer(self) -> bool:
        return isinstance(self, IntegerType)

    @property
    def is_signless_integer(self) -> bool:
        return isinstance(self, IntegerType) and self.signedness == "signless"

    def bitwidth(self) -> Optional[int]:
        return None


class IntegerType(Type):
    """``iN``, ``siN`` or ``uiN``."""

    __slots__ = ("width", "signedness")

    def __init__(self, width: int, signedness: str = "signless") -> None:
        if width < 0:
            raise ValueError(f"integer width must be non-negative, got {width}")
        if signedness not in ("signless", "signed", "unsigned"):
            raise ValueError(f"invalid signedness {signedness!r}")
        self.width = int(width)
        self.signedness = signedness

    def __str__(self) -> str:
        prefix = {"signless": "i", "signed": "si", "unsigned": "ui"}[self.signedness]
        return f"{prefix}{self.width}"

    def bitwidth(self) -> Optional[int]:
        return self.width

    @property
    def is_signed(self) -> bool:
        return self.signedness == "signed"

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    @staticmethod
    def get(width: int, signedness: str = "signless") -> "IntegerType":
        ctx = get_default_context()
        prefix = {"signless": "i", "signed": "si", "unsigned": "ui"}[signedness]
        key = f"{prefix}{width}"
        return ctx.get_or_create_type(key, lambda: IntegerType(width, signedness))  # type: ignore[return-value]


class FloatType(Type):
    """``f16`` / ``f32`` / ``f64`` / ``bf16``."""

    __slots__ = ("width", "mnemonic")

    def __init__(self, width: int, mnemonic: Optional[str] = None) -> None:
        self.width = int(width)
        self.mnemonic = mnemonic or f"f{width}"

    def __str__(self) -> str:
        return self.mnemonic

    def bitwidth(self) -> Optional[int]:
        return self.width


class IndexType(Type):
    """The ``index`` type."""

    def __str__(self) -> str:
        return "index"


class NoneType_(Type):
    """The ``none`` type (spelled ``NoneType_`` to avoid clashing with builtins)."""

    def __str__(self) -> str:
        return "none"


class FunctionType(Type):
    """``(i32, i32) -> i32``."""

    __slots__ = ("inputs", "results")

    def __init__(self, inputs: Sequence[Type], results: Sequence[Type]) -> None:
        self.inputs: Tuple[Type, ...] = tuple(inputs)
        self.results: Tuple[Type, ...] = tuple(results)

    def __str__(self) -> str:
        ins = ", ".join(str(t) for t in self.inputs)
        if len(self.results) == 1:
            outs = str(self.results[0])
        else:
            outs = "(" + ", ".join(str(t) for t in self.results) + ")"
        return f"({ins}) -> {outs}"

    @property
    def num_inputs(self) -> int:
        return len(self.inputs)

    @property
    def num_results(self) -> int:
        return len(self.results)


class TupleType(Type):
    """``tuple<i32, i32>``."""

    __slots__ = ("element_types",)

    def __init__(self, element_types: Sequence[Type]) -> None:
        self.element_types: Tuple[Type, ...] = tuple(element_types)

    def __str__(self) -> str:
        return "tuple<" + ", ".join(str(t) for t in self.element_types) + ">"


class OpaqueType(Type):
    """A dialect type this core layer does not model, e.g. ``!seq.clock``."""

    __slots__ = ("dialect", "mnemonic", "data")

    def __init__(self, dialect: str, mnemonic: str, data: str = "") -> None:
        self.dialect = dialect
        self.mnemonic = mnemonic
        self.data = data

    def __str__(self) -> str:
        body = f"{self.dialect}.{self.mnemonic}"
        if self.data:
            body += f"<{self.data}>"
        return f"!{body}"


# ---------------------------------------------------------------------------
# Attributes
# ---------------------------------------------------------------------------


class Attribute(ABC):
    """Base class for all MLIR attributes."""

    @abstractmethod
    def __str__(self) -> str:
        ...

    @property
    def value(self) -> Any:
        return None

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Attribute):
            return NotImplemented
        return type(self) is type(other) and str(self) == str(other)

    def __ne__(self, other: object) -> bool:
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self) -> int:
        return hash((type(self).__name__, str(self)))

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"{type(self).__name__}({str(self)!r})"


class UnitAttr(Attribute):
    def __str__(self) -> str:
        return "unit"

    @property
    def value(self) -> Any:
        return True


class BoolAttr(Attribute):
    __slots__ = ("_value",)

    def __init__(self, value: bool) -> None:
        self._value = bool(value)

    def __str__(self) -> str:
        return "true" if self._value else "false"

    @property
    def value(self) -> bool:
        return self._value


class IntegerAttr(Attribute):
    __slots__ = ("_value", "type")

    def __init__(self, value: int, type: Optional[Type] = None) -> None:
        self._value = int(value)
        self.type = type

    def __str__(self) -> str:
        if self.type is None:
            return str(self._value)
        return f"{self._value} : {self.type}"

    @property
    def value(self) -> int:
        return self._value


class FloatAttr(Attribute):
    __slots__ = ("_value", "type")

    def __init__(self, value: float, type: Optional[Type] = None) -> None:
        self._value = float(value)
        self.type = type

    def __str__(self) -> str:
        if self.type is None:
            return repr(self._value)
        return f"{self._value} : {self.type}"

    @property
    def value(self) -> float:
        return self._value


class StringAttr(Attribute):
    __slots__ = ("_value",)

    def __init__(self, value: str) -> None:
        self._value = str(value)

    def __str__(self) -> str:
        escaped = self._value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'

    @property
    def value(self) -> str:
        return self._value


class TypeAttr(Attribute):
    __slots__ = ("_type",)

    def __init__(self, type: Type) -> None:
        self._type = type

    def __str__(self) -> str:
        return str(self._type)

    @property
    def value(self) -> Type:
        return self._type


class ArrayAttr(Attribute):
    __slots__ = ("_elements",)

    def __init__(self, elements: Sequence[Attribute]) -> None:
        self._elements: Tuple[Attribute, ...] = tuple(elements)

    def __str__(self) -> str:
        return "[" + ", ".join(str(e) for e in self._elements) + "]"

    @property
    def value(self) -> Tuple[Attribute, ...]:
        return self._elements

    def __len__(self) -> int:
        return len(self._elements)

    def __iter__(self) -> Iterator[Attribute]:
        return iter(self._elements)


class DictAttr(Attribute):
    __slots__ = ("_entries",)

    def __init__(self, entries: Optional[Dict[str, Attribute]] = None) -> None:
        self._entries: Dict[str, Attribute] = dict(entries or {})

    def __str__(self) -> str:
        inner = ", ".join(f"{k} = {v}" for k, v in self._entries.items())
        return "{" + inner + "}"

    @property
    def value(self) -> Dict[str, Attribute]:
        return dict(self._entries)

    def __getitem__(self, key: str) -> Attribute:
        return self._entries[key]

    def get(self, key: str, default: Any = None) -> Any:
        return self._entries.get(key, default)


class FlatSymbolRefAttr(Attribute):
    """``@symbol``."""

    __slots__ = ("_symbol",)

    def __init__(self, symbol: str) -> None:
        self._symbol = symbol.lstrip("@")

    def __str__(self) -> str:
        return f"@{self._symbol}"

    @property
    def value(self) -> str:
        return self._symbol


# ---------------------------------------------------------------------------
# Values and uses
# ---------------------------------------------------------------------------


class OpOperand:
    """A single use edge: ``owner``'s operand ``index`` refers to ``value``."""

    __slots__ = ("owner", "index", "value")

    def __init__(self, owner: "Operation", index: int, value: "Value") -> None:
        self.owner = owner
        self.index = index
        self.value = value

    def set(self, value: "Value") -> None:
        if self.value is value:
            return
        self.value.remove_use(self)
        self.value = value
        value.add_use(self)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"OpOperand({self.owner.name}#{self.index})"


class Value(ABC):
    """An SSA value: either an :class:`OpResult` or a :class:`BlockArgument`."""

    def __init__(self, type: Type, name: Optional[str] = None) -> None:
        self.type = type
        self.name = name
        self._uses: List[OpOperand] = []

    # -- use lists --------------------------------------------------------
    @property
    def uses(self) -> List[OpOperand]:
        return list(self._uses)

    @property
    def users(self) -> List["Operation"]:
        seen: List["Operation"] = []
        for use in self._uses:
            if use.owner not in seen:
                seen.append(use.owner)
        return seen

    def add_use(self, use: OpOperand) -> None:
        self._uses.append(use)

    def remove_use(self, use: OpOperand) -> None:
        try:
            self._uses.remove(use)
        except ValueError:
            pass

    @property
    def has_uses(self) -> bool:
        return bool(self._uses)

    @property
    def use_count(self) -> int:
        return len(self._uses)

    def replace_all_uses_with(self, other: "Value") -> int:
        """Point every use of ``self`` at ``other``.  Returns the use count."""
        if other is self:
            return 0
        count = 0
        for use in list(self._uses):
            use.value = other
            other.add_use(use)
            count += 1
        self._uses.clear()
        return count

    # -- naming -----------------------------------------------------------
    @property
    def defining_op(self) -> Optional["Operation"]:
        return None

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        label = self.name or "?"
        return f"{type(self).__name__}(%{label} : {self.type})"


class OpResult(Value):
    """A value produced by an operation."""

    def __init__(
        self,
        owner: "Operation",
        index: int,
        type: Type,
        name: Optional[str] = None,
    ) -> None:
        super().__init__(type, name)
        self.owner = owner
        self.index = index

    @property
    def defining_op(self) -> Optional["Operation"]:
        return self.owner


class BlockArgument(Value):
    """A value produced by a block's parameter list."""

    def __init__(
        self,
        owner: "Block",
        index: int,
        type: Type,
        name: Optional[str] = None,
    ) -> None:
        super().__init__(type, name)
        self.owner = owner
        self.index = index

    @property
    def block(self) -> "Block":
        return self.owner


class WalkOrder(Enum):
    PRE_ORDER = auto()
    POST_ORDER = auto()


# ---------------------------------------------------------------------------
# Operations
# ---------------------------------------------------------------------------

_OP_IDS = itertools.count()


class Operation:
    """A generic MLIR operation.

    Subclasses in the dialect modules add sugar (accessors, folders, verifiers)
    but the storage lives here so that generic passes work on anything.
    """

    #: Overridden by subclasses via :meth:`operation_name`.
    OPERATION_NAME: Optional[str] = None
    TRAITS: Tuple[Trait, ...] = ()

    def __init__(
        self,
        name: Optional[str] = None,
        operands: Optional[Sequence[Value]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        successors: Optional[Sequence["Block"]] = None,
        regions: Optional[Sequence["Region"]] = None,
        num_regions: int = 0,
        location: Optional[Location] = None,
        result_names: Optional[Sequence[Optional[str]]] = None,
    ) -> None:
        self._name = name or self.operation_name()
        if self._name is None:
            raise ValueError("operation requires a name")
        self.uid = next(_OP_IDS)
        self.location = location or Location.unknown()
        self.attributes: Dict[str, Attribute] = dict(attributes or {})
        self.parent: Optional["Block"] = None

        self._operands: List[OpOperand] = []
        for value in operands or ():
            self.add_operand(value)

        names = list(result_names or ())
        self._results: List[OpResult] = []
        for index, rtype in enumerate(result_types or ()):
            rname = names[index] if index < len(names) else None
            self._results.append(OpResult(self, index, rtype, rname))

        self.successors: List["Block"] = list(successors or ())
        self.regions: List["Region"] = []
        for region in regions or ():
            self.add_region(region)
        for _ in range(num_regions):
            self.add_region(Region())

    # -- identity ---------------------------------------------------------
    @classmethod
    def operation_name(cls) -> Optional[str]:
        return cls.OPERATION_NAME

    @property
    def name(self) -> str:
        return self._name

    @property
    def op_name(self) -> str:
        return self._name

    @property
    def dialect_name(self) -> str:
        return self._name.split(".")[0] if "." in self._name else ""

    @property
    def mnemonic(self) -> str:
        return self._name.split(".", 1)[1] if "." in self._name else self._name

    # -- traits -----------------------------------------------------------
    @classmethod
    def traits(cls) -> Tuple[Trait, ...]:
        return cls.TRAITS

    def has_trait(self, trait: Trait) -> bool:
        return trait in self.traits()

    @property
    def is_terminator(self) -> bool:
        return self.has_trait(Trait.TERMINATOR)

    @property
    def is_pure(self) -> bool:
        return self.has_trait(Trait.PURE) or self.has_trait(Trait.CONSTANT_LIKE)

    @property
    def is_constant_like(self) -> bool:
        return self.has_trait(Trait.CONSTANT_LIKE)

    # -- operands ---------------------------------------------------------
    @property
    def operands(self) -> List[Value]:
        return [use.value for use in self._operands]

    @property
    def op_operands(self) -> List[OpOperand]:
        return list(self._operands)

    @property
    def num_operands(self) -> int:
        return len(self._operands)

    def operand(self, index: int) -> Value:
        return self._operands[index].value

    def add_operand(self, value: Value) -> OpOperand:
        use = OpOperand(self, len(self._operands), value)
        value.add_use(use)
        self._operands.append(use)
        return use

    def set_operand(self, index: int, value: Value) -> None:
        self._operands[index].set(value)

    def set_operands(self, values: Sequence[Value]) -> None:
        self.drop_all_operand_uses()
        self._operands = []
        for value in values:
            self.add_operand(value)

    def drop_all_operand_uses(self) -> None:
        for use in self._operands:
            use.value.remove_use(use)

    # -- results ----------------------------------------------------------
    @property
    def results(self) -> List[OpResult]:
        return list(self._results)

    @property
    def num_results(self) -> int:
        return len(self._results)

    def result(self, index: int = 0) -> OpResult:
        return self._results[index]

    @property
    def result_types(self) -> List[Type]:
        return [r.type for r in self._results]

    def add_result(self, type: Type, name: Optional[str] = None) -> OpResult:
        res = OpResult(self, len(self._results), type, name)
        self._results.append(res)
        return res

    # -- attributes -------------------------------------------------------
    def get_attr(self, name: str, default: Any = None) -> Any:
        return self.attributes.get(name, default)

    def set_attr(self, name: str, attr: Attribute) -> None:
        self.attributes[name] = attr

    def remove_attr(self, name: str) -> Optional[Attribute]:
        return self.attributes.pop(name, None)

    def has_attr(self, name: str) -> bool:
        return name in self.attributes

    def attr_value(self, name: str, default: Any = None) -> Any:
        attr = self.attributes.get(name)
        return default if attr is None else attr.value

    # -- regions ----------------------------------------------------------
    def add_region(self, region: Optional["Region"] = None) -> "Region":
        region = region if region is not None else Region()
        region.parent = self
        self.regions.append(region)
        return region

    @property
    def num_regions(self) -> int:
        return len(self.regions)

    def region(self, index: int = 0) -> "Region":
        return self.regions[index]

    @property
    def body(self) -> "Region":
        if not self.regions:
            self.add_region(Region())
        return self.regions[0]

    # -- position ---------------------------------------------------------
    @property
    def parent_block(self) -> Optional["Block"]:
        return self.parent

    @property
    def parent_region(self) -> Optional["Region"]:
        return self.parent.parent if self.parent is not None else None

    @property
    def parent_op(self) -> Optional["Operation"]:
        region = self.parent_region
        return region.parent if region is not None else None

    def get_parent_of_name(self, name: str) -> Optional["Operation"]:
        op = self.parent_op
        while op is not None:
            if op.name == name:
                return op
            op = op.parent_op
        return None

    def is_before_in_block(self, other: "Operation") -> bool:
        if self.parent is None or self.parent is not other.parent:
            return False
        ops = self.parent.operations
        return ops.index(self) < ops.index(other)

    # -- mutation ---------------------------------------------------------
    def detach(self) -> "Operation":
        """Remove from the parent block without dropping operand uses."""
        if self.parent is not None:
            self.parent.remove(self)
        return self

    def erase(self) -> None:
        """Drop all uses and remove from the parent block."""
        for region in self.regions:
            region.erase_all_blocks()
        self.drop_all_operand_uses()
        self._operands = []
        self.detach()

    def replace_all_uses_with(self, values: Sequence[Value]) -> int:
        if len(values) != len(self._results):
            raise ValueError(
                f"cannot replace {len(self._results)} results with {len(values)} values"
            )
        return sum(
            res.replace_all_uses_with(new) for res, new in zip(self._results, values)
        )

    def clone(self, value_map: Optional[Dict[Value, Value]] = None) -> "Operation":
        value_map = {} if value_map is None else value_map
        new_operands = [value_map.get(v, v) for v in self.operands]
        clone = Operation(
            name=self._name,
            operands=new_operands,
            result_types=self.result_types,
            attributes=dict(self.attributes),
            successors=list(self.successors),
            location=self.location,
            result_names=[r.name for r in self._results],
        )
        for region in self.regions:
            clone.add_region(region.clone(value_map))
        for old, new in zip(self._results, clone.results):
            value_map[old] = new
        return clone

    # -- traversal --------------------------------------------------------
    def walk(
        self,
        callback: Callable[["Operation"], Any],
        order: WalkOrder = WalkOrder.PRE_ORDER,
    ) -> None:
        if order is WalkOrder.PRE_ORDER:
            callback(self)
        for region in list(self.regions):
            for block in list(region.blocks):
                for op in list(block.operations):
                    op.walk(callback, order)
        if order is WalkOrder.POST_ORDER:
            callback(self)

    def walk_ops(self, order: WalkOrder = WalkOrder.PRE_ORDER) -> List["Operation"]:
        collected: List["Operation"] = []
        self.walk(collected.append, order)
        return collected

    # -- folding hook -----------------------------------------------------
    def fold(self) -> Optional[List[Any]]:
        """Constant-fold in place.

        Returns a list of Python constants (one per result) when the operation
        can be folded, ``None`` otherwise.  Overridden by dialect operations.
        """
        return None

    # -- verification -----------------------------------------------------
    def verify(self) -> List[str]:
        errors: List[str] = []
        if self.has_trait(Trait.SAME_OPERANDS_AND_RESULT_TYPE):
            types = self.result_types + [v.type for v in self.operands]
            if types and any(t != types[0] for t in types):
                errors.append(
                    f"'{self.name}' requires all operands and results to have the "
                    f"same type, got {[str(t) for t in types]}"
                )
        errors.extend(self.verify_op())
        for region in self.regions:
            errors.extend(region.verify())
        return errors

    def verify_op(self) -> List[str]:
        """Hook for op-specific verification."""
        return []

    # -- printing ---------------------------------------------------------
    def __str__(self) -> str:
        from .printer import print_op

        return print_op(self)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Operation {self._name} operands={self.num_operands} results={self.num_results}>"


# ---------------------------------------------------------------------------
# Blocks
# ---------------------------------------------------------------------------


class Block:
    """An ordered list of operations with SSA arguments."""

    def __init__(
        self,
        arg_types: Optional[Sequence[Type]] = None,
        label: Optional[str] = None,
        arg_names: Optional[Sequence[Optional[str]]] = None,
    ) -> None:
        self.label = label
        self.parent: Optional["Region"] = None
        self.arguments: List[BlockArgument] = []
        self.operations: List[Operation] = []
        names = list(arg_names or ())
        for index, atype in enumerate(arg_types or ()):
            aname = names[index] if index < len(names) else None
            self.add_argument(atype, aname)

    # -- arguments --------------------------------------------------------
    def add_argument(self, type: Type, name: Optional[str] = None) -> BlockArgument:
        arg = BlockArgument(self, len(self.arguments), type, name)
        self.arguments.append(arg)
        return arg

    @property
    def num_arguments(self) -> int:
        return len(self.arguments)

    def argument(self, index: int) -> BlockArgument:
        return self.arguments[index]

    @property
    def argument_types(self) -> List[Type]:
        return [a.type for a in self.arguments]

    # -- operation list ---------------------------------------------------
    def append(self, op: Operation) -> Operation:
        op.parent = self
        self.operations.append(op)
        return op

    add = append

    def push_front(self, op: Operation) -> Operation:
        op.parent = self
        self.operations.insert(0, op)
        return op

    def insert(self, index: int, op: Operation) -> Operation:
        op.parent = self
        self.operations.insert(index, op)
        return op

    def insert_before(self, existing: Operation, op: Operation) -> Operation:
        return self.insert(self.operations.index(existing), op)

    def insert_after(self, existing: Operation, op: Operation) -> Operation:
        return self.insert(self.operations.index(existing) + 1, op)

    def remove(self, op: Operation) -> None:
        try:
            self.operations.remove(op)
        except ValueError:
            return
        op.parent = None

    def erase_all_operations(self) -> None:
        for op in reversed(list(self.operations)):
            op.erase()

    @property
    def terminator(self) -> Optional[Operation]:
        if self.operations and self.operations[-1].is_terminator:
            return self.operations[-1]
        return None

    @property
    def num_operations(self) -> int:
        return len(self.operations)

    @property
    def successors(self) -> List["Block"]:
        term = self.terminator
        return list(term.successors) if term is not None else []

    @property
    def predecessors(self) -> List["Block"]:
        preds: List["Block"] = []
        if self.parent is None:
            return preds
        for block in self.parent.blocks:
            if self in block.successors and block not in preds:
                preds.append(block)
        return preds

    # -- traversal --------------------------------------------------------
    def walk(
        self,
        callback: Callable[[Operation], Any],
        order: WalkOrder = WalkOrder.PRE_ORDER,
    ) -> None:
        for op in list(self.operations):
            op.walk(callback, order)

    def clone(self, value_map: Optional[Dict[Value, Value]] = None) -> "Block":
        value_map = {} if value_map is None else value_map
        clone = Block(arg_types=self.argument_types, label=self.label,
                      arg_names=[a.name for a in self.arguments])
        for old, new in zip(self.arguments, clone.arguments):
            value_map[old] = new
        for op in self.operations:
            clone.append(op.clone(value_map))
        return clone

    # -- verification -----------------------------------------------------
    def verify(self) -> List[str]:
        errors: List[str] = []
        for index, op in enumerate(self.operations):
            if op.is_terminator and index != len(self.operations) - 1:
                errors.append(
                    f"terminator '{op.name}' must be the last operation in its block"
                )
            errors.extend(op.verify())
        return errors

    def __iter__(self) -> Iterator[Operation]:
        return iter(self.operations)

    def __len__(self) -> int:
        return len(self.operations)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Block {self.label or '^entry'} ops={len(self.operations)}>"


# ---------------------------------------------------------------------------
# Regions
# ---------------------------------------------------------------------------


class Region:
    """An ordered list of blocks owned by an operation."""

    def __init__(self, blocks: Optional[Sequence[Block]] = None) -> None:
        self.parent: Optional[Operation] = None
        self.blocks: List[Block] = []
        for block in blocks or ():
            self.add_block(block)

    def add_block(self, block: Optional[Block] = None) -> Block:
        block = block if block is not None else Block()
        block.parent = self
        self.blocks.append(block)
        return block

    def insert_block(self, index: int, block: Block) -> Block:
        block.parent = self
        self.blocks.insert(index, block)
        return block

    @property
    def entry_block(self) -> Optional[Block]:
        return self.blocks[0] if self.blocks else None

    @property
    def num_blocks(self) -> int:
        return len(self.blocks)

    def block(self, index: int = 0) -> Block:
        return self.blocks[index]

    def find_block(self, label: str) -> Optional[Block]:
        for block in self.blocks:
            if block.label == label:
                return block
        return None

    def erase_all_blocks(self) -> None:
        for block in reversed(list(self.blocks)):
            block.erase_all_operations()
        self.blocks.clear()

    @property
    def operations(self) -> List[Operation]:
        """Flattened view of the operations in every block of this region."""
        return [op for block in self.blocks for op in block.operations]

    def walk(
        self,
        callback: Callable[[Operation], Any],
        order: WalkOrder = WalkOrder.PRE_ORDER,
    ) -> None:
        for block in list(self.blocks):
            block.walk(callback, order)

    def clone(self, value_map: Optional[Dict[Value, Value]] = None) -> "Region":
        value_map = {} if value_map is None else value_map
        clone = Region()
        for block in self.blocks:
            clone.add_block(block.clone(value_map))
        return clone

    def verify(self) -> List[str]:
        errors: List[str] = []
        for block in self.blocks:
            errors.extend(block.verify())
        return errors

    def __iter__(self) -> Iterator[Block]:
        return iter(self.blocks)

    def __len__(self) -> int:
        return len(self.blocks)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Region blocks={len(self.blocks)}>"


# ---------------------------------------------------------------------------
# Module
# ---------------------------------------------------------------------------


class ModuleOp(Operation):
    """``builtin.module`` - the top-level container with one region/block."""

    OPERATION_NAME = "builtin.module"
    TRAITS = (Trait.SYMBOL_TABLE, Trait.SINGLE_BLOCK, Trait.NO_TERMINATOR,
              Trait.ISOLATED_FROM_ABOVE)

    def __init__(
        self,
        name: Optional[str] = None,
        location: Optional[Location] = None,
        context: Optional[MLIRContext] = None,
    ) -> None:
        attributes: Dict[str, Attribute] = {}
        if name:
            attributes["sym_name"] = StringAttr(name)
        super().__init__(
            name="builtin.module",
            attributes=attributes,
            location=location,
        )
        self.context = context if context is not None else get_default_context()
        region = self.add_region(Region())
        region.add_block(Block())

    @property
    def sym_name(self) -> Optional[str]:
        attr = self.attributes.get("sym_name")
        return attr.value if attr is not None else None

    @property
    def block(self) -> Block:
        return self.regions[0].blocks[0]

    @property
    def ops(self) -> List[Operation]:
        return list(self.block.operations)

    def append(self, op: Operation) -> Operation:
        return self.block.append(op)

    def lookup_symbol(self, name: str) -> Optional[Operation]:
        return SymbolTable(self).lookup(name)

    @property
    def symbol_table(self) -> "SymbolTable":
        return SymbolTable(self)


# ---------------------------------------------------------------------------
# Symbol tables
# ---------------------------------------------------------------------------


class SymbolTable:
    """Maps ``sym_name`` attributes of the direct children of an op to ops."""

    SYMBOL_ATTR = "sym_name"

    def __init__(self, op: Operation) -> None:
        self.op = op
        self._symbols: Dict[str, Operation] = {}
        for region in op.regions:
            for block in region.blocks:
                for child in block.operations:
                    name = SymbolTable.get_symbol_name(child)
                    if name is not None:
                        self._symbols[name] = child

    @staticmethod
    def get_symbol_name(op: Operation) -> Optional[str]:
        attr = op.attributes.get(SymbolTable.SYMBOL_ATTR)
        if attr is None:
            return None
        return attr.value

    def lookup(self, name: str) -> Optional[Operation]:
        return self._symbols.get(name.lstrip("@"))

    def insert(self, op: Operation) -> None:
        name = SymbolTable.get_symbol_name(op)
        if name is not None:
            self._symbols[name] = op

    @property
    def symbols(self) -> Dict[str, Operation]:
        return dict(self._symbols)

    def names(self) -> List[str]:
        return list(self._symbols)

    def __len__(self) -> int:
        return len(self._symbols)

    def __contains__(self, name: str) -> bool:
        return name.lstrip("@") in self._symbols

    def __iter__(self) -> Iterator[str]:
        return iter(self._symbols)


# ---------------------------------------------------------------------------
# Builders
# ---------------------------------------------------------------------------


class InsertionPoint:
    """Where a builder inserts newly created operations."""

    def __init__(self, block: Block, index: Optional[int] = None) -> None:
        self.block = block
        self.index = index

    @staticmethod
    def at_block_begin(block: Block) -> "InsertionPoint":
        return InsertionPoint(block, 0)

    @staticmethod
    def at_block_end(block: Block) -> "InsertionPoint":
        return InsertionPoint(block, None)

    @staticmethod
    def before(op: Operation) -> "InsertionPoint":
        if op.parent is None:
            raise ValueError("operation has no parent block")
        return InsertionPoint(op.parent, op.parent.operations.index(op))

    @staticmethod
    def after(op: Operation) -> "InsertionPoint":
        if op.parent is None:
            raise ValueError("operation has no parent block")
        return InsertionPoint(op.parent, op.parent.operations.index(op) + 1)

    def insert(self, op: Operation) -> Operation:
        if self.index is None:
            return self.block.append(op)
        inserted = self.block.insert(self.index, op)
        self.index += 1
        return inserted


class OpBuilder:
    """Creates operations at a tracked insertion point."""

    def __init__(self, insertion_point: Optional[InsertionPoint] = None) -> None:
        self.insertion_point = insertion_point

    def set_insertion_point(self, point: InsertionPoint) -> None:
        self.insertion_point = point

    def set_insertion_point_to_end(self, block: Block) -> None:
        self.insertion_point = InsertionPoint.at_block_end(block)

    def set_insertion_point_before(self, op: Operation) -> None:
        self.insertion_point = InsertionPoint.before(op)

    def insert(self, op: Operation) -> Operation:
        if self.insertion_point is None:
            return op
        return self.insertion_point.insert(op)

    def create(
        self,
        name: str,
        operands: Optional[Sequence[Value]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        successors: Optional[Sequence[Block]] = None,
        result_names: Optional[Sequence[Optional[str]]] = None,
        location: Optional[Location] = None,
    ) -> Operation:
        op = Operation(
            name=name,
            operands=operands,
            result_types=result_types,
            attributes=attributes,
            successors=successors,
            result_names=result_names,
            location=location,
        )
        return self.insert(op)


# ---------------------------------------------------------------------------
# Verifier
# ---------------------------------------------------------------------------


class Verifier:
    """Runs structural verification over an operation tree."""

    @staticmethod
    def verify(op: Operation, raise_on_error: bool = False) -> List[str]:
        errors = op.verify()
        errors.extend(Verifier._verify_dominance(op))
        if errors and raise_on_error:
            raise VerificationError("; ".join(errors))
        return errors

    @staticmethod
    def _verify_dominance(root: Operation) -> List[str]:
        """Check that values are defined before use inside each single block.

        Multi-block regions are checked loosely (definition must appear in some
        block of the enclosing region or an ancestor), which is enough to catch
        the mistakes the parser and the rewriters can make.
        """
        errors: List[str] = []

        def check_block(block: Block) -> None:
            defined: List[Value] = list(block.arguments)
            for op in block.operations:
                for value in op.operands:
                    if isinstance(value, OpResult):
                        owner = value.owner
                        if owner.parent is block and owner not in _preceding(block, op):
                            errors.append(
                                f"operand of '{op.name}' does not dominate its use"
                            )
                defined.extend(op.results)

        def _preceding(block: Block, op: Operation) -> List[Operation]:
            index = block.operations.index(op)
            return block.operations[:index]

        def visit(op: Operation) -> None:
            for region in op.regions:
                for block in region.blocks:
                    check_block(block)

        root.walk(visit)
        return errors

toolUseResult.content:
"""Core MLIR IR data structures.

This module is the foundation of the whole stack: the CIRCT hardware dialects in
:mod:`src.circt` and the K-inspired semantic layer in :mod:`src.k_circt` are both
built on the operations / blocks / regions / modules defined here.

The design mirrors upstream MLIR closely enough that the concepts transfer:

* :class:`MLIRContext` owns dialect registration and uniqued types.
* :class:`Type` and :class:`Attribute` are immutable, hashable value objects.
* :class:`Value` is either an :class:`OpResult` or a :class:`BlockArgument`, and
  tracks its uses so that ``replace_all_uses_with`` and DCE are cheap.
* :class:`Operation` holds operands, results, attributes, successors and nested
  :class:`Region` objects; regions hold :class:`Block` objects; blocks hold
  operations.  That is the classic MLIR three-level nesting.
"""
from __future__ import annotations

import itertools
from abc import ABC, abstractmethod
from enum import Enum, auto
from typing import (
    Any,
    Callable,
    Dict,
    Iterable,
    Iterator,
    List,
    Optional,
    Sequence,
    Tuple,
)

__all__ = [
    "MLIRContext",
    "Dialect",
    "Location",
    "Trait",
    "Type",
    "IntegerType",
    "FloatType",
    "IndexType",
    "NoneType_",
    "FunctionType",
    "TupleType",
    "OpaqueType",
    "Attribute",
    "UnitAttr",
    "BoolAttr",
    "IntegerAttr",
    "FloatAttr",
    "StringAttr",
    "TypeAttr",
    "ArrayAttr",
    "DictAttr",
    "FlatSymbolRefAttr",
    "Value",
    "OpResult",
    "BlockArgument",
    "OpOperand",
    "Operation",
    "Block",
    "Region",
    "ModuleOp",
    "OpBuilder",
    "InsertionPoint",
    "Verifier",
    "VerificationError",
    "ParseError",
    "WalkOrder",
    "SymbolTable",
    "get_default_context",
    "reset_default_context",
]


class ParseError(Exception):
    """Raised when the textual IR cannot be parsed."""

    def __init__(self, message: str, line: int = 0, column: int = 0) -> None:
        self.message = message
        self.line = line
        self.column = column
        if line:
            super().__init__(f"{line}:{column}: {message}")
        else:
            super().__init__(message)


class VerificationError(Exception):
    """Raised when the IR fails verification."""


# ---------------------------------------------------------------------------
# Context / dialects
# ---------------------------------------------------------------------------


class MLIRContext:
    """Owns dialect registration and the uniqued type/attribute caches."""

    def __init__(self, allow_unregistered_dialects: bool = True) -> None:
        self._dialects: Dict[str, "Dialect"] = {}
        self._type_cache: Dict[str, "Type"] = {}
        self._attr_cache: Dict[str, "Attribute"] = {}
        self.allow_unregistered_dialects = allow_unregistered_dialects

    # -- dialects ---------------------------------------------------------
    def register_dialect(self, dialect: "Dialect") -> "Dialect":
        self._dialects[dialect.name] = dialect
        return dialect

    def get_dialect(self, name: str) -> Optional["Dialect"]:
        return self._dialects.get(name)

    def get_or_load_dialect(self, name: str) -> Optional["Dialect"]:
        return self._dialects.get(name)

    @property
    def dialects(self) -> Dict[str, "Dialect"]:
        return dict(self._dialects)

    def is_registered_operation(self, name: str) -> bool:
        dialect_name = name.split(".")[0]
        dialect = self._dialects.get(dialect_name)
        if dialect is None:
            return False
        return dialect.get_operation(name) is not None

    def lookup_operation(self, name: str) -> Optional[type]:
        dialect_name = name.split(".")[0]
        dialect = self._dialects.get(dialect_name)
        if dialect is None:
            return None
        return dialect.get_operation(name)

    # -- uniquing ---------------------------------------------------------
    def get_or_create_type(self, key: str, factory: Callable[[], "Type"]) -> "Type":
        cached = self._type_cache.get(key)
        if cached is None:
            cached = factory()
            self._type_cache[key] = cached
        return cached

    def get_or_create_attribute(
        self, key: str, factory: Callable[[], "Attribute"]
    ) -> "Attribute":
        cached = self._attr_cache.get(key)
        if cached is None:
            cached = factory()
            self._attr_cache[key] = cached
        return cached

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"MLIRContext(dialects={sorted(self._dialects)})"


_DEFAULT_CONTEXT: Optional[MLIRContext] = None


def get_default_context() -> MLIRContext:
    """Return the process-wide default context, creating it on first use.

    Dialect modules register themselves against this context at import time so
    that ``parse(...)`` works without any explicit setup.
    """
    global _DEFAULT_CONTEXT
    if _DEFAULT_CONTEXT is None:
        _DEFAULT_CONTEXT = MLIRContext()
    return _DEFAULT_CONTEXT


def reset_default_context() -> MLIRContext:
    global _DEFAULT_CONTEXT
    _DEFAULT_CONTEXT = MLIRContext()
    return _DEFAULT_CONTEXT


class Dialect:
    """A namespace of operations, types and attributes."""

    def __init__(self, name: str, context: Optional[MLIRContext] = None) -> None:
        self.name = name
        self.context = context if context is not None else get_default_context()
        self._operations: Dict[str, type] = {}
        self._type_parsers: Dict[str, Callable[[str], "Type"]] = {}
        self.context.register_dialect(self)

    # -- operations -------------------------------------------------------
    def register_operation(self, op_class: type) -> type:
        self._operations[op_class.operation_name()] = op_class
        return op_class

    def get_operation(self, name: str) -> Optional[type]:
        return self._operations.get(name)

    @property
    def operations(self) -> Dict[str, type]:
        return dict(self._operations)

    # -- types ------------------------------------------------------------
    def register_type_parser(self, mnemonic: str, parser: Callable[[str], "Type"]) -> None:
        self._type_parsers[mnemonic] = parser

    def parse_type(self, mnemonic: str, body: str) -> Optional["Type"]:
        parser = self._type_parsers.get(mnemonic)
        if parser is None:
            return None
        return parser(body)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"Dialect({self.name!r}, ops={len(self._operations)})"


# ---------------------------------------------------------------------------
# Locations
# ---------------------------------------------------------------------------


class Location:
    """Source location attached to an operation."""

    __slots__ = ("filename", "line", "column", "name")

    def __init__(
        self,
        filename: Optional[str] = None,
        line: int = 0,
        column: int = 0,
        name: Optional[str] = None,
    ) -> None:
        self.filename = filename
        self.line = line
        self.column = column
        self.name = name

    @staticmethod
    def unknown() -> "Location":
        return Location()

    @staticmethod
    def file_line_col(filename: str, line: int, column: int = 0) -> "Location":
        return Location(filename=filename, line=line, column=column)

    @property
    def is_unknown(self) -> bool:
        return self.filename is None and self.name is None

    def __str__(self) -> str:
        if self.name is not None:
            return f'loc("{self.name}")'
        if self.filename is None:
            return "loc(unknown)"
        return f'loc("{self.filename}":{self.line}:{self.column})'

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"Location({self})"


