            output_types = list(ftype.results) if ftype is not None else []
            output_index = 0
            for name_attr, dir_attr in zip(port_names, port_dirs):
                direction = dir_attr.value
                if direction in ("in", "inout"):
                    if block is not None and input_index < len(block.arguments):
                        arg = block.arguments[input_index]
                        rendered = self._name_state.get_value_name(arg)
                        ptype = arg.type
                    else:
                        rendered = f"%{name_attr.value}"
                        ptype = (ftype.inputs[input_index] if ftype and
                                 input_index < len(ftype.inputs) else None)
