        if value_attr is not None and not op.num_operands:
            pieces.append(self._format_value_attribute(value_attr))

        operand_texts = [self._name_state.get_value_name(v) for v in op.operands]
        if op.name == "seq.compreg" and len(operand_texts) >= 4:
            pieces.append(", ".join(operand_texts[:2]))
            pieces.append("reset")
            pieces.append(", ".join(operand_texts[2:]))
        elif operand_texts:
            pieces.append(", ".join(operand_texts))
        elif isinstance(keywords, ArrayAttr) and op.name not in _KEYWORD_FIRST_OPS:
            pieces.extend(k.value for k in keywords)

