            succ = ", ".join(self._name_state.get_block_name(b) for b in op.successors)
            if operand_texts:
                pieces[-1] = pieces[-1] + ","
            pieces.append(succ)

        attr_text = self._format_attributes(op.attributes)
        if attr_text:
            pieces.append(attr_text)

        type_text = self._format_trailing_type(op)
        if type_text:
            pieces.append(type_text)

        return " ".join(p for p in pieces if p)

    def _format_value_attribute(self, attr: Attribute) -> str:
        if isinstance(attr, IntegerAttr):
            return str(attr.value)
        if isinstance(attr, StringAttr):
            return str(attr)
        return str(attr)

    def _format_attributes(self, attrs: Dict[str, Attribute]) -> str:
        visible = {k: v for k, v in attrs.items() if k not in _ELIDED_ATTRIBUTES}
        if not visible:
            return ""
        inner = ", ".join(f"{k} = {v}" for k, v in visible.items())
        return "{" + inner + "}"

    def _format_trailing_type(self, op: Operation) -> str:
        if op.name in _PRINT_OPERAND_TYPE_OPS and op.num_operands:
            return f": {op.operands[0].type}"
        if op.num_results:
            types = [str(t) for t in op.result_types]
            unique = sorted(set(types))
            if len(unique) == 1:
                return f": {types[0]}"
            return ": " + ", ".join(types)
        if op.num_operands and op.name not in ("cf.br", "cf.cond_br", "cf.switch"):
            return f": {op.operands[0].type}"
        return ""

    # -- regions / blocks -------------------------------------------------
    def _print_region(self, region: Region) -> None:
        self._indent_level += 1
        for index, block in enumerate(region.blocks):
            self._print_block(block, is_entry=index == 0)
        self._indent_level -= 1

    def _print_block(self, block: Block, is_entry: bool) -> None:
        if not is_entry or (block.label and block.arguments and not is_entry):
            label = self._name_state.get_block_name(block)
            args = ""
            if block.arguments:
                rendered = ", ".join(
                    f"{self._name_state.get_value_name(a)}: {a.type}"
                    for a in block.arguments
                )
                args = f"({rendered})"
            self._write_line(f"{label}{args}:")
        for op in block.operations:
            self._print_op(op)


