"""Rewrite patterns, the pattern rewriter and the greedy rewrite driver.

This is the machinery the ``arith`` sample program exercises: a worklist-driven
greedy driver that repeatedly folds operations into ``arith.constant`` and
applies canonicalisation patterns until the IR stops changing.
"""
from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable, Dict, List, Optional, Sequence, Set, Tuple

from .ir import (
    Attribute,
    Block,
    IntegerAttr,
    IntegerType,
    Operation,
    OpResult,
    Region,
    Trait,
    Type,
    Value,
)
from .dialects import arith as arith_dialect

__all__ = [
    "PatternBenefit",
    "Pattern",
    "RewritePattern",
    "OpRewritePattern",
    "RewritePatternSet",
    "PatternRewriter",
    "OperationFolder",
    "GreedyRewriteConfig",
    "GreedyPatternRewriteDriver",
    "PatternApplicator",
    "apply_patterns_greedily",
    "canonicalization_patterns",
    "FoldConstantsPattern",
    "AddZeroPattern",
    "MulOnePattern",
    "MulZeroPattern",
    "SubSelfPattern",
]


class PatternBenefit:
    """How valuable a pattern is; higher benefits are tried first."""

    def __init__(self, benefit: int = 1) -> None:
        if benefit < 0:
            raise ValueError("pattern benefit must be non-negative")
        self._benefit = int(benefit)

    @property
    def value(self) -> int:
        return self._benefit

    @staticmethod
    def impossible() -> "PatternBenefit":
        return PatternBenefit(0)

    def __lt__(self, other: "PatternBenefit") -> bool:
        return self._benefit < other._benefit

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, PatternBenefit):
            return NotImplemented
        return self._benefit == other._benefit

    def __hash__(self) -> int:
        return hash(self._benefit)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"PatternBenefit({self._benefit})"


class Pattern(ABC):
    """Base class for anything that matches operations."""

    def __init__(self, root_op_name: Optional[str] = None, benefit: int = 1) -> None:
        self._root_op_name = root_op_name
        self._benefit = PatternBenefit(benefit)

    @property
    def root_operation_name(self) -> Optional[str]:
        return self._root_op_name

    @property
    def benefit(self) -> PatternBenefit:
        return self._benefit

    @property
    def name(self) -> str:
        return type(self).__name__

    def match(self, op: Operation) -> bool:
        if self._root_op_name is None:
            return True
        return op.name == self._root_op_name


class RewritePattern(Pattern):
    """A pattern that rewrites the operations it matches."""

    @abstractmethod
    def match_and_rewrite(self, op: Operation, rewriter: "PatternRewriter") -> bool:
        ...


class OpRewritePattern(RewritePattern):
    """A :class:`RewritePattern` keyed on a single operation name."""

    def __init__(self, op_name: Optional[str] = None, benefit: int = 1) -> None:
        super().__init__(root_op_name=op_name, benefit=benefit)


class RewritePatternSet:
    """An ordered collection of patterns, highest benefit first."""

    def __init__(self, patterns: Optional[Sequence[RewritePattern]] = None) -> None:
        self._patterns: List[RewritePattern] = list(patterns or ())
        self._sort()

    def _sort(self) -> None:
        self._patterns.sort(key=lambda p: p.benefit.value, reverse=True)

    def add(self, pattern: RewritePattern) -> "RewritePatternSet":
        self._patterns.append(pattern)
        self._sort()
        return self

    def extend(self, patterns: Sequence[RewritePattern]) -> "RewritePatternSet":
        self._patterns.extend(patterns)
        self._sort()
        return self

    @property
    def patterns(self) -> List[RewritePattern]:
        return list(self._patterns)

    def patterns_for(self, op: Operation) -> List[RewritePattern]:
        return [p for p in self._patterns if p.match(op)]

    def __len__(self) -> int:
        return len(self._patterns)

    def __iter__(self):
        return iter(self._patterns)


class PatternRewriter:
    """The only sanctioned way for a pattern to mutate the IR.

    Every mutation is recorded so the greedy driver knows which operations to
    revisit and how many rewrites happened.
    """

    def __init__(self) -> None:
        self._erased_ops: List[Operation] = []
        self._created_ops: List[Operation] = []
        self._replaced_ops: List[Operation] = []
        self._modified_ops: List[Operation] = []
        self._insertion_point: Optional[Tuple[Block, int]] = None
        self.worklist_hook: Optional[Callable[[Operation], None]] = None

    # -- bookkeeping ------------------------------------------------------
    @property
    def erased_ops(self) -> List[Operation]:
        return list(self._erased_ops)

    @property
    def created_ops(self) -> List[Operation]:
        return list(self._created_ops)

    @property
    def replaced_ops(self) -> List[Operation]:
        return list(self._replaced_ops)

    @property
    def modified_ops(self) -> List[Operation]:
        return list(self._modified_ops)

    def reset(self) -> None:
        self._erased_ops.clear()
        self._created_ops.clear()
        self._replaced_ops.clear()
        self._modified_ops.clear()

    def _notify(self, op: Operation) -> None:
        if self.worklist_hook is not None:
            self.worklist_hook(op)

    # -- insertion --------------------------------------------------------
    def set_insertion_point_before(self, op: Operation) -> None:
        if op.parent is None:
            raise ValueError("operation is not attached to a block")
        self._insertion_point = (op.parent, op.parent.operations.index(op))

    def set_insertion_point_after(self, op: Operation) -> None:
        if op.parent is None:
            raise ValueError("operation is not attached to a block")
        self._insertion_point = (op.parent, op.parent.operations.index(op) + 1)

    def insert_before(self, op: Operation, new_op: Operation) -> Operation:
        if op.parent is None:
            raise ValueError("operation is not attached to a block")
        op.parent.insert_before(op, new_op)
        self._created_ops.append(new_op)
        return new_op

    def insert_after(self, op: Operation, new_op: Operation) -> Operation:
        if op.parent is None:
            raise ValueError("operation is not attached to a block")
        op.parent.insert_after(op, new_op)
        self._created_ops.append(new_op)
        return new_op

    def create_operation(
        self,
        name: str,
        operands: Optional[Sequence[Value]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        result_names: Optional[Sequence[Optional[str]]] = None,
    ) -> Operation:
        op = Operation(
            name=name,
            operands=operands,
            result_types=result_types,
            attributes=attributes,
            result_names=result_names,
        )
        if self._insertion_point is not None:
            block, index = self._insertion_point
            block.insert(index, op)
            self._insertion_point = (block, index + 1)
        self._created_ops.append(op)
        return op

    def create_constant(
        self,
        value: int,
        result_type: Type,
        before: Optional[Operation] = None,
        result_name: Optional[str] = None,
    ) -> Operation:
        """Materialise an ``arith.constant`` (optionally before ``before``)."""
        constant = arith_dialect.ConstantOp(
            value=value,
            result_type=result_type,
            result_names=[result_name] if result_name else None,
        )
        if before is not None:
            self.insert_before(before, constant)
        elif self._insertion_point is not None:
            block, index = self._insertion_point
            block.insert(index, constant)
            self._insertion_point = (block, index + 1)
            self._created_ops.append(constant)
        else:
            self._created_ops.append(constant)
        return constant

    # -- replacement ------------------------------------------------------
    def replace_op(self, op: Operation, new_values: Sequence[Value]) -> None:
        for user in op_users(op):
            self._notify(user)
        op.replace_all_uses_with(list(new_values))
        self._replaced_ops.append(op)
        op.erase()
        self._erased_ops.append(op)

    def replace_op_with_new_op(self, op: Operation, new_op: Operation) -> None:
        self.insert_before(op, new_op)
        self.replace_op(op, new_op.results)

    def erase_op(self, op: Operation) -> None:
        for value in op.operands:
            defining = value.defining_op
            if defining is not None:
                self._notify(defining)
        op.erase()
        self._erased_ops.append(op)

    def modify_op_in_place(self, op: Operation) -> None:
        self._modified_ops.append(op)
        self._notify(op)


def op_users(op: Operation) -> List[Operation]:
    users: List[Operation] = []
    for result in op.results:
        for user in result.users:
            if user not in users:
                users.append(user)
    return users


# ---------------------------------------------------------------------------
# Folding
# ---------------------------------------------------------------------------


class OperationFolder:
    """Turns foldable operations into materialised constants.

    Constants are uniqued per block so folding a chain does not leave a trail of
    duplicate ``arith.constant`` operations.
    """

    def __init__(self, constant_op_name: str = "arith.constant") -> None:
        self.constant_op_name = constant_op_name
        self._constant_cache: Dict[Tuple[int, str, Any], Operation] = {}
        self.num_folded = 0
        self.num_constants_created = 0

    def clear(self) -> None:
        self._constant_cache.clear()

    def try_fold(self, op: Operation, rewriter: PatternRewriter) -> bool:
        """Fold ``op`` if possible.  Returns ``True`` when the IR changed."""
        if op.is_constant_like:
            return False
        if not op.num_results or not op.is_pure:
            return False
        folded = op.fold()
        if not folded or len(folded) != op.num_results:
            return False

        replacements: List[Value] = []
        for constant, result in zip(folded, op.results):
            if isinstance(constant, Value):
                replacements.append(constant)
                continue
            if not isinstance(constant, int):
                return False
            replacements.append(
                self._get_or_create_constant(constant, result.type, op, rewriter)
            )
        rewriter.replace_op(op, replacements)
        self.num_folded += 1
        return True

    def _get_or_create_constant(
        self,
        value: int,
        result_type: Type,
        anchor: Operation,
        rewriter: PatternRewriter,
    ) -> Value:
        block = anchor.parent
        key = (id(block), str(result_type), value)
        cached = self._constant_cache.get(key)
        if cached is not None and cached.parent is block:
            return cached.result(0)
        constant = rewriter.create_constant(value, result_type, before=anchor)
        self.num_constants_created += 1
        self._constant_cache[key] = constant
        return constant.result(0)


# ---------------------------------------------------------------------------
# Canonicalisation patterns
# ---------------------------------------------------------------------------


def _constant_value(value: Value) -> Optional[int]:
    defining = value.defining_op
    if defining is None or not defining.is_constant_like:
        return None
    folded = defining.fold()
    if not folded or not isinstance(folded[0], int):
        return None
    return folded[0]


class FoldConstantsPattern(RewritePattern):
    """Applies :class:`OperationFolder` to every foldable operation."""

    def __init__(self, folder: Optional[OperationFolder] = None, benefit: int = 4) -> None:
        super().__init__(root_op_name=None, benefit=benefit)
        self.folder = folder if folder is not None else OperationFolder()

    def match(self, op: Operation) -> bool:
        return op.num_results > 0 and op.is_pure and not op.is_constant_like

    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        return self.folder.try_fold(op, rewriter)


class _IdentityOperandPattern(OpRewritePattern):
    """``op(x, identity) -> x`` for a commutative-ish binary operation."""

    IDENTITY = 0

    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        if op.num_operands != 2 or op.num_results != 1:
            return False
        lhs, rhs = op.operands
        if _constant_value(rhs) == self.IDENTITY:
            rewriter.replace_op(op, [lhs])
            return True
        if _constant_value(lhs) == self.IDENTITY:
            rewriter.replace_op(op, [rhs])
            return True
        return False


class AddZeroPattern(_IdentityOperandPattern):
    """``arith.addi %x, 0 -> %x``."""

    IDENTITY = 0

    def __init__(self, op_name: str = "arith.addi", benefit: int = 2) -> None:
        super().__init__(op_name=op_name, benefit=benefit)


class MulOnePattern(_IdentityOperandPattern):
    """``arith.muli %x, 1 -> %x``."""

    IDENTITY = 1

    def __init__(self, op_name: str = "arith.muli", benefit: int = 2) -> None:
        super().__init__(op_name=op_name, benefit=benefit)


class MulZeroPattern(OpRewritePattern):
    """``arith.muli %x, 0 -> 0``."""

    def __init__(self, op_name: str = "arith.muli", benefit: int = 3) -> None:
        super().__init__(op_name=op_name, benefit=benefit)

    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        if op.num_operands != 2 or op.num_results != 1:
            return False
        if 0 not in (_constant_value(op.operands[0]), _constant_value(op.operands[1])):
            return False
        zero = rewriter.create_constant(0, op.result(0).type, before=op)
        rewriter.replace_op(op, [zero.result(0)])
        return True


class SubSelfPattern(OpRewritePattern):
    """``arith.subi %x, %x -> 0``."""

    def __init__(self, op_name: str = "arith.subi", benefit: int = 3) -> None:
        super().__init__(op_name=op_name, benefit=benefit)

    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        if op.num_operands != 2 or op.num_results != 1:
            return False
        if op.operands[0] is not op.operands[1]:
            return False
        zero = rewriter.create_constant(0, op.result(0).type, before=op)
        rewriter.replace_op(op, [zero.result(0)])
        return True


def canonicalization_patterns(
    folder: Optional[OperationFolder] = None,
) -> RewritePatternSet:
    """The default canonicalisation pattern set."""
    return RewritePatternSet(
        [
            FoldConstantsPattern(folder),
            MulZeroPattern(),
            SubSelfPattern(),
            AddZeroPattern(),
            AddZeroPattern(op_name="arith.subi"),
            AddZeroPattern(op_name="arith.ori"),
            AddZeroPattern(op_name="arith.xori"),
            MulOnePattern(),
        ]
    )


# ---------------------------------------------------------------------------
# Greedy driver
# ---------------------------------------------------------------------------


class GreedyRewriteConfig:
    """Knobs for :class:`GreedyPatternRewriteDriver`."""

    def __init__(
        self,
        max_iterations: int = 10,
        max_num_rewrites: int = -1,
        fold: bool = True,
        cse_constants: bool = True,
        region_simplification: bool = True,
    ) -> None:
        self.max_iterations = max_iterations
        self.max_num_rewrites = max_num_rewrites
        self.fold = fold
        self.cse_constants = cse_constants
        self.region_simplification = region_simplification


class GreedyPatternRewriteDriver:
    """Worklist-based greedy rewriter.

    Operations are seeded onto a worklist in post-order; each pop tries every
    matching pattern by descending benefit.  Whenever a rewrite happens the
    users of the rewritten operation are pushed back so that folding cascades
    (``42 + 17`` folds to ``59``, which lets ``59 * 5`` fold to ``295``).
    """

    def __init__(
        self,
        patterns: RewritePatternSet,
        config: Optional[GreedyRewriteConfig] = None,
    ) -> None:
        self.patterns = patterns
        self.config = config if config is not None else GreedyRewriteConfig()
        self.num_rewrites = 0
        self.num_iterations = 0
        self._worklist: List[Operation] = []
        self._worklist_set: Set[int] = set()
        self._dead: Set[int] = set()

    # -- worklist ---------------------------------------------------------
    def _push(self, op: Operation) -> None:
        if id(op) in self._dead or id(op) in self._worklist_set:
            return
        self._worklist.append(op)
        self._worklist_set.add(id(op))

    def _pop(self) -> Optional[Operation]:
        while self._worklist:
            op = self._worklist.pop()
            self._worklist_set.discard(id(op))
            if id(op) in self._dead:
                continue
            return op
        return None

    def _seed(self, root: Operation) -> None:
        collected: List[Operation] = []

        def visit(op: Operation) -> None:
            if op is not root:
                collected.append(op)

        root.walk(visit)
        # Reverse so that, popping from the end, we process operations in
        # source order - the natural direction for forward constant folding.
        for op in reversed(collected):
            self._push(op)

    # -- driver -----------------------------------------------------------
    def simplify(self, root: Operation) -> bool:
        changed = False
        rewriter = PatternRewriter()
        rewriter.worklist_hook = self._push

        for _ in range(max(1, self.config.max_iterations)):
            self.num_iterations += 1
            self._worklist.clear()
            self._worklist_set.clear()
            self._seed(root)
            iteration_changed = False

            while True:
                op = self._pop()
                if op is None:
                    break
                if op.parent is None:
                    continue
                for pattern in self.patterns.patterns_for(op):
                    if self.config.max_num_rewrites >= 0 and (
                        self.num_rewrites >= self.config.max_num_rewrites
                    ):
                        return changed
                    rewriter.reset()
                    if pattern.match_and_rewrite(op, rewriter):
                        self.num_rewrites += 1
                        iteration_changed = True
                        changed = True
                        for erased in rewriter.erased_ops:
                            self._dead.add(id(erased))
                        for created in rewriter.created_ops:
                            self._push(created)
                        break

            if not iteration_changed:
                break

        return changed


class PatternApplicator:
    """Convenience wrapper exposing greedy application plus statistics."""

    def __init__(
        self,
        patterns: Sequence[RewritePattern] | RewritePatternSet,
        config: Optional[GreedyRewriteConfig] = None,
    ) -> None:
        if isinstance(patterns, RewritePatternSet):
            self.patterns = patterns
        else:
            self.patterns = RewritePatternSet(list(patterns))
        self.config = config if config is not None else GreedyRewriteConfig()
        self._statistics: Dict[str, int] = {"num_rewrites": 0, "num_iterations": 0}

    def apply_patterns_greedy(self, op: Operation) -> bool:
        driver = GreedyPatternRewriteDriver(self.patterns, self.config)
        changed = driver.simplify(op)
        self._statistics["num_rewrites"] += driver.num_rewrites
        self._statistics["num_iterations"] += driver.num_iterations
        return changed

    @property
    def statistics(self) -> Dict[str, int]:
        return dict(self._statistics)


def apply_patterns_greedily(
    root: Operation,
    patterns: Sequence[RewritePattern] | RewritePatternSet,
    config: Optional[GreedyRewriteConfig] = None,
) -> bool:
    """Apply ``patterns`` to ``root`` until nothing changes."""
    pattern_set = (
        patterns if isinstance(patterns, RewritePatternSet)
        else RewritePatternSet(list(patterns))
    )
    return GreedyPatternRewriteDriver(pattern_set, config).simplify(root)

