class HWModuleOp(HWOp):
    """``hw.module @Name(in %a: i4, out r: i4) { ... }``.

    The body is a *graph region*: operations may refer to values defined further
    down, which is how ``inputs/counter.mlir`` closes the loop between
    ``seq.compreg`` and the ``comb.add`` that feeds it.
    """

    OPERATION_NAME = "hw.module"
    TRAITS = (
        Trait.SYMBOL,
        Trait.ISOLATED_FROM_ABOVE,
        Trait.GRAPH_REGION,
        Trait.SINGLE_BLOCK,
    )

    def __init__(
        self,
        name: Optional[str] = None,
        ports: Optional[Sequence[Port]] = None,
        body: Optional[Sequence[Operation]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        port_list = list(ports or ())
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs["sym_name"] = StringAttr(name)
        attrs["port_names"] = ArrayAttr([StringAttr(p.name) for p in port_list])
        attrs["port_directions"] = ArrayAttr(
            [StringAttr(p.direction.value) for p in port_list]
        )
        attrs["function_type"] = TypeAttr(
            FunctionType(
                [p.port_type for p in port_list if not p.is_output and p.port_type],
                [p.port_type for p in port_list if p.is_output and p.port_type],
            )
        )
        Operation.__init__(
            self,
            name=self.OPERATION_NAME,
            attributes=attrs,
            location=location,
        )
        self._symbolic_operands = None
        self._declared_width = 0
        self.result_name = ""

        region = self.add_region(Region())
        block = region.add_block(Block())
        for port in port_list:
            if not port.is_output:
                block.add_argument(port.port_type or IntType(1), port.name)
        for op in body or ():
            if isinstance(op, Operation):
                block.append(op)

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> "Operation":
        op = cls.__new__(cls)
        Operation.__init__(op, **kwargs)
        op._symbolic_operands = None
        op._declared_width = 0
        op.result_name = ""
        return op

    # -- structure --------------------------------------------------------
    @property
    def module_name(self) -> Optional[str]:
        attr = self.attributes.get("sym_name")
        return attr.value if attr is not None else None

    #: CIRCT spells the symbol ``name``; :class:`Operation` uses that for the
    #: op mnemonic, so the module symbol is exposed as ``module_name`` too.
    @property
    def sym_name(self) -> Optional[str]:
        return self.module_name

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        """The operations in the module body, in textual order."""
        block = self.block
        return list(block.operations) if block is not None else []

    @property
    def ports(self) -> List[Port]:
        names = self.attributes.get("port_names")
        directions = self.attributes.get("port_directions")
        ftype = self.attributes.get("function_type")
        signature = ftype.value if ftype is not None else None
        if not isinstance(names, ArrayAttr) or not isinstance(directions, ArrayAttr):
            return []
        inputs = list(signature.inputs) if signature is not None else []
        outputs = list(signature.results) if signature is not None else []
        result: List[Port] = []
        in_index = out_index = 0
        for name_attr, dir_attr in zip(names, directions):
            direction = Direction.parse(dir_attr.value)
            if direction is Direction.OUTPUT:
                ptype = outputs[out_index] if out_index < len(outputs) else None
                out_index += 1
            else:
                ptype = inputs[in_index] if in_index < len(inputs) else None
                in_index += 1
            result.append(Port(name_attr.value, ptype, direction))
        return result

    @property
    def input_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_input]

    @property
    def output_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_output]

    @property
    def inout_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_inout]

    def get_port(self, name: str) -> Optional[Port]:
        for port in self.ports:
            if port.name == name:
                return port
        return None

    def total_input_bits(self) -> int:
        return sum(p.bit_width() for p in self.input_ports)

    def total_output_bits(self) -> int:
        return sum(p.bit_width() for p in self.output_ports)

    @property
    def output_op(self) -> Optional[Operation]:
        for op in reversed(self.body):
            if op.name == "hw.output":
                return op
        return None

    # -- verification -----------------------------------------------------
    def verify_signature(self) -> List[str]:
        errors: List[str] = []
        seen: set = set()
        for port in self.ports:
            if port.name in seen:
                errors.append(f"Duplicate port name: {port.name}")
            seen.add(port.name)
            if port.bit_width() == 0:
                errors.append(f"Port {port.name} has zero width")
        output = self.output_op
        expected = len(self.output_ports)
        if output is not None and output.num_operands != expected:
            errors.append(
                f"OutputOp has {output.num_operands} operands but module has "
                f"{expected} output ports"
            )
        return errors

    def verify_op(self) -> List[str]:
        errors = list(self.verify_signature())
        if self.module_name is None:
            errors.append("'hw.module' requires a 'sym_name' attribute")
        return errors


class HWModuleExternOp(HWModuleOp):
    """``hw.module.extern`` - a declaration with no body."""

    OPERATION_NAME = "hw.module.extern"


class ConstantOp(HWOp):
    """``hw.constant 5 : i4``."""

    OPERATION_NAME = "hw.constant"
    TRAITS = (Trait.PURE, Trait.CONSTANT_LIKE)

    def __init__(
        self,
        value: Optional[int] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        types = list(result_types or ())
        if not types:
            types = [IntType(width if width > 0 else 32)]
        if value is not None:
            attrs.setdefault("value", IntegerAttr(int(value), types[0]))
        super().__init__(
            result_types=types,
            attributes=attrs,
            width=width,
            result_name=result_name,
            location=location,
        )

    @property
    def value(self) -> int:
        attr = self.attributes.get("value")
        if attr is None:
            return 0
        raw = attr.value
        return int(raw) if isinstance(raw, (int, float)) else 0

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.truncate(self.value)

    def fold(self) -> Optional[List[Any]]:
        return [self.evaluate()]

    def is_zero(self) -> bool:
        return self.evaluate() == 0

    def is_all_ones(self) -> bool:
        return self.evaluate() == self.mask()


class OutputOp(HWOp):
    """``hw.output %a, %b : i4, i4`` - the module terminator."""

    OPERATION_NAME = "hw.output"
    TRAITS = (Trait.TERMINATOR, Trait.PURE)

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(operands=operands, location=location)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    def operand_count(self) -> int:
        return self.num_operands

    def evaluate(self, env: Optional[SignalEnv] = None) -> List[int]:
        return self.read_operands(env or {})

    def fold(self) -> Optional[List[Any]]:
        return None


class WireOp(HWOp):
    """``hw.wire %value : i4`` - a named, assignable signal."""

    OPERATION_NAME = "hw.wire"
    TRAITS = (Trait.PURE,)

    def __init__(
        self,
        name: Optional[str] = None,
        wire_type: Optional[Type] = None,
        value: Optional[Union[Value, str, int]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        location: Optional[Location] = None,
        result_types: Optional[Sequence[Type]] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        self._literal: Optional[int] = None
        if isinstance(value, (Value, str)):
            ops.append(value)
        elif isinstance(value, int):
            self._literal = value
        attrs: Dict[str, Attribute] = {}
        if name:
            attrs["name"] = StringAttr(name)
        types = list(result_types or ())
        if not types and wire_type is not None:
            types = [wire_type]
        super().__init__(
            operands=ops,
            result_types=types,
            attributes=attrs,
            name=self.OPERATION_NAME,
            location=location,
        )
        self.wire_name = name or ""

    def bit_width(self) -> int:
        return self.width

    def assign(self, value: int) -> None:
        self._literal = int(value)

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        if self.num_operands:
            return self.truncate(self.read_operand(env or {}, 0))
        return self.truncate(self._literal or 0)


