class ArrayCreateOp(HWOp):
    """``hw.array_create`` - build an array from element values."""

    OPERATION_NAME = "hw.array_create"
    TRAITS = (Trait.PURE,)

    def __init__(
        self,
        elements: Optional[Sequence[Union[Value, str]]] = None,
        element_type: Optional[Type] = None,
        result_name: str = "",
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops = list(elements or ()) or list(operands or ())
        types = list(result_types or ())
        if not types and element_type is not None and ops:
            types = [ArrayType(element_type, len(ops))]
        super().__init__(
            operands=ops,
            result_types=types,
            result_name=result_name,
            location=location,
        )
        self.element_type = element_type

    def size(self) -> int:
        return self.num_operands

    def result_type(self) -> Optional[Type]:
        if self.element_type is None:
            return None
        return ArrayType(self.element_type, max(1, self.size()))

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        """Pack the elements into one integer, element 0 in the low bits."""
        env = env or {}
        width = bit_width_of(self.element_type) or 1
        packed = 0
        for index, raw in enumerate(self.read_operands(env)):
            packed |= (raw & ((1 << width) - 1)) << (index * width)
        return packed


class ArrayGetOp(HWOp):
    """``hw.array_get %array[%index]``."""

    OPERATION_NAME = "hw.array_get"
    TRAITS = (Trait.PURE,)

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        element_width: int = 0,
        result_types: Optional[Sequence[Type]] = None,
        result_name: str = "",
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=element_width,
            result_name=result_name,
            location=location,
        )

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        env = env or {}
        packed = self.read_operand(env, 0)
        index = self.read_operand(env, 1)
        width = self.width or 1
        return (packed >> (index * width)) & ((1 << width) - 1)


